def test_load_config_returns_defaults(state_dir: Path) -> None:
    config = load_config(repo_path=state_dir)
    assert config["jira"] == []
    assert config["github"]["repos"] == []
    assert "primary" in config["calendars"]


def test_save_and_load_roundtrip(state_dir: Path) -> None:
    config = {"jira": [{"key": "TEST-1", "tier": "active"}]}
    save_config(config, repo_path=state_dir)
    loaded = load_config(repo_path=state_dir)
    assert loaded["jira"][0]["key"] == "TEST-1"


def test_add_jira_tracking(state_dir: Path) -> None:
    add_jira_tracking("ANSTRAT-1900", tier="active", repo_path=state_dir)
    config = load_config(repo_path=state_dir)
    assert len(config["jira"]) == 1
    assert config["jira"][0]["key"] == "ANSTRAT-1900"
    assert config["jira"][0]["tier"] == "active"


def test_add_jira_tracking_updates_existing(state_dir: Path) -> None:
    add_jira_tracking("TEST-1", tier="awareness", repo_path=state_dir)
    add_jira_tracking("TEST-1", tier="active", repo_path=state_dir)
    config = load_config(repo_path=state_dir)
    assert len(config["jira"]) == 1
    assert config["jira"][0]["tier"] == "active"


